cat("\n═══ Riepilogo ═══════════════════════════════════════════════\n")
print(table(.verifica$esito))
if (any(.verifica$esito == "DIVERSO")) { cat("\nControlli non superati:\n"); print(.verifica[.verifica$esito == "DIVERSO", c("lab", "controllo", "dettaglio")], row.names = FALSE) } else cat("\nTutti i controlli eseguiti sono superati.\n")
dir.create("verifica/runs", recursive = TRUE, showWarnings = FALSE)
write.csv(.verifica, "verifica/runs/parita_C_17_25_esiti.csv", row.names = FALSE)
cat("Esiti salvati in verifica/runs/parita_C_17_25_esiti.csv\n")

# Macrofase C strict gate: skipped, missing or mismatching checks are FAILURE.
if (any(.verifica$esito != "OK") || length(unique(.verifica$lab[grepl("^[0-9][0-9]$",.verifica$lab)])) != 9) {
  stop("Numerical R/JS parity not demonstrated for all expected labs")
}
cat("PARITY 17_25 PASS: 9 labs; build SHA-256 50fe9d20ccd31304a6eaf972c7f8a33612120f150c22fd89c0801c279f9715c5\n")
